// Até 4 termos separados por vírgula (variações de nome: "Redacted, Redacted, Ypiranga") = documento com QUALQUER um.
// Separados por & ("Redacted & Rosemara & Mister") = documento com TODOS (usado pelas menções, para achar o assunto certo).
// Busca só Google Docs (ATAs, resumos de chat) e .txt de TRANSCRIÇÃO — arquivos .txt de cliente (ex.: sped.txt) ficam de fora.
const bruto = String($input.first().json.termos || '');
const todos = bruto.includes('&');
const termos = bruto.split(todos ? /&/ : /[,;]/).map(t => t.trim().replace(/['\\]/g, '')).filter(Boolean).slice(0, 4);
if (!termos.length) return [{ json: { vazio: true, termos: [], q: '' } }];
const q = '(' + termos.map(t => "fullText contains '" + t + "'").join(todos ? ' and ' : ' or ') + ") and (mimeType = 'application/vnd.google-apps.document' or (mimeType = 'text/plain' and name contains 'Transcri')) and trashed = false";
return [{ json: { vazio: false, termos, q } }];

// O Drive não ordena busca de texto por data, então ordena aqui: resumos de chat e ATAs primeiro, depois o resto; dentro de cada grupo, o mais recente primeiro.
// Lê até 6 documentos (antes eram 4: o chat certo ficava de fora quando havia muitos documentos recentes).
const prioridade = n => /^Chats REDACTED|ATA|\d{4}-\d{2}-\d{2} \d{2}h\d{2}/i.test(n) ? 0 : 1;
const arquivos = ($input.first().json.files || []).sort((a, b) => (prioridade(a.name) - prioridade(b.name)) || String(b.modifiedTime).localeCompare(String(a.modifiedTime)));
if (!arquivos.length) return [{ json: { vazio: true } }];
const outros = arquivos.slice(6, 15).map(f => f.name + ' (' + String(f.modifiedTime).slice(0, 10) + ')');
return arquivos.slice(0, 6).map(f => ({ json: { vazio: false, id: f.id, nome: f.name, data: String(f.modifiedTime).slice(0, 10), link: f.webViewLink, gdoc: f.mimeType === 'application/vnd.google-apps.document', outros } }));

// Para cada documento, pega até 2 trechos (~1.200 caracteres) em volta de onde os termos aparecem JUNTOS (ou do termo mais raro).
// Compara sem acento e sem maiúscula ("Redacted" acha "REDACTED").
// Mostra QUAIS termos aparecem em cada documento, para o agente não atribuir documento de um cliente a outro.
const termos = $('Montar busca').first().json.termos;
const docs = $('Escolher os 4 mais recentes').all().map(i => i.json);
const lidos = $input.all().map(i => i.json);
if (!termos.length) return [{ json: { resultado: 'Informe pelo menos um termo (ex.: nome do cliente e variações separadas por vírgula).' } }];
if (docs[0].vazio) return [{ json: { resultado: 'Nada encontrado em ATAs, transcrições ou resumos de chat para: ' + termos.join(', ') + '. Tente variações de grafia, nome da empresa ou do sócio. Se ainda assim não achar, o assunto provavelmente não foi registrado por escrito.' } }];
const norm = s => Array.from(String(s)).map(c => (c.normalize('NFD').replace(/[̀-ͯ]/g, '')[0] || c).toLowerCase()).join('');
const ts = termos.map(norm);
let out = 'Busca por: ' + termos.join(', ') + '\nATENÇÃO: só ligue um documento a um cliente/pessoa se o NOME dele estiver em "Termos encontrados". Documento que só tem palavras genéricas é de OUTRO assunto/cliente.\n\n';
docs.forEach((d, i) => {
  const texto = String((lidos[i] || {}).conteudo || '');
  const n = norm(texto);
  const achados = termos.filter((t, k) => n.includes(ts[k]));
  // Posições de cada termo; pontua janelas onde aparecem mais termos diferentes juntos.
  const pos = [];
  ts.forEach((t, k) => { let p = n.indexOf(t); let c = 0; while (p >= 0 && c < 40) { pos.push({ p, k }); p = n.indexOf(t, p + t.length); c++; } });
  const janelas = pos.map(a => ({ p: a.p, score: new Set(pos.filter(b => Math.abs(b.p - a.p) < 900).map(b => b.k)).size })).sort((a, b) => b.score - a.score || a.p - b.p);
  const escolhidos = [];
  janelas.forEach(w => { if (escolhidos.length < 2 && escolhidos.every(e => Math.abs(e - w.p) > 1200)) escolhidos.push(w.p); });
  out += '===== ' + d.nome + ' (' + d.data + ') =====\nLink: ' + d.link + '\nTermos encontrados neste documento: ' + (achados.length ? achados.join(', ') : 'NENHUM — não use este documento') + '\n';
  if (!texto) out += '(não consegui ler o conteúdo)\n\n';
  else if (!escolhidos.length) out += '(o Drive indicou o termo, mas não achei o trecho exato)\n\n';
  else escolhidos.forEach(p => { out += '... ' + texto.slice(Math.max(0, p - 600), p + 600).replace(/\s+/g, ' ') + ' ...\n\n'; });
});
const outros = docs[0].outros || [];
if (outros.length) out += 'Outros documentos que citam algum dos termos (sem conferir qual): ' + outros.join('; ');
return [{ json: { resultado: out.slice(0, 20000) } }];
